function parseRemainderAnswer(raw){const s=String(raw??'').trim().toLowerCase().replace(/−/g,'-');const m=s.match(/^(-?\d+)\s*(?:[,;]\s*|\s+|\(\s*)(?:ост(?:аток)?\.?\s*)?(-?\d+)\s*\)?$/i);return m?[Number(m[1]),Number(m[2])]:null}
